import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Site","description":"","frontmatter":{"prev":{"text":"Structure","link":"/documentation/structure"},"next":{"text":"Site Settings","link":"/documentation/site/site-settings"}},"headers":[],"relativePath":"documentation/site/site.md","filePath":"documentation/site/site.md","lastUpdated":1788551488000}`),a={name:`documentation/site/site.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="site" tabindex="-1">Site <a class="header-anchor" href="#site" aria-label="Permalink to “Site”">​</a></h1><p>A <strong>Site</strong> is the top-level container in Excellent Data Filler representing a web application or domain where you want to automate workflows. It acts as the central hub grouping together all related <strong>Site Forms</strong>, <strong>Segments</strong>, <strong>Excel Data Templates</strong>, <strong>Scraper Results</strong>, and <strong>Site Settings</strong>.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Sites serve as the foundational root of your automation projects:</p><ul><li><strong>Project Organization</strong>: Keeps forms, fields, and routines grouped under a dedicated domain profile.</li><li><strong>Centralized Control</strong>: Manage site-wide environment variables, column mappings, and backup configurations in one location.</li><li><strong>Multi-Page Coordination</strong>: Link multiple sequential forms and segments together using the unique Site ID.</li></ul><hr><h2 id="site-management-dashboard" tabindex="-1">Site Management Dashboard <a class="header-anchor" href="#site-management-dashboard" aria-label="Permalink to “Site Management Dashboard”">​</a></h2><p>The site management interface provides a dashboard of all registered sites:</p><img src="/image/site-01.png" alt="Site Management Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><p>Each site card displays its title, description, active status toggle, and quick-action buttons to access forms, settings, and templates.</p><hr><h2 id="insert-site" tabindex="-1">Insert Site <a class="header-anchor" href="#insert-site" aria-label="Permalink to “Insert Site”">​</a></h2><p>There are two primary methods to register a new site in Excellent Data Filler:</p><h3 id="method-1-context-menu-keyboard-shortcut-recommended" tabindex="-1">Method 1: Context Menu &amp; Keyboard Shortcut (Recommended) <a class="header-anchor" href="#method-1-context-menu-keyboard-shortcut-recommended" aria-label="Permalink to “Method 1: Context Menu &amp; Keyboard Shortcut (Recommended)”">​</a></h3><p>The quickest way to register a site while browsing:</p><ol><li><strong>Navigate to the Target Page</strong>: Open the target website in your browser.</li><li><strong>Trigger Site Registration</strong>: <ul><li>Press the keyboard shortcut <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>, or</li><li>Right-click anywhere on the page and select <strong>Insert Site</strong> from the context menu.</li></ul></li><li><strong>Automatic Configuration</strong>: The extension automatically captures the current page URL, creates the root site record, and registers the initial form page schema.</li><li><strong>Configure Settings</strong>: Open the extension popup to customize field mappings and timing delays.</li></ol><blockquote><p><strong>Tip:</strong> If a web page blocks right-clicking, ensure <strong>Allow Right Click?</strong> is turned ON in <a href="/documentation/settings.html#advanced-options">Extension Settings</a>, or use the keyboard shortcut <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd>.</p></blockquote><h3 id="method-2-manual-site-creation" tabindex="-1">Method 2: Manual Site Creation <a class="header-anchor" href="#method-2-manual-site-creation" aria-label="Permalink to “Method 2: Manual Site Creation”">​</a></h3><p>If you prefer to create a site manually before navigating to the target website:</p><ol><li>Open the extension popup and navigate to the <strong>Sites</strong> dashboard.</li><li>Click the <strong>Insert a new Site</strong> button (<code>+</code>).</li><li>Fill in the site details: <ul><li><strong>Site Title</strong>: A descriptive name identifying the project (e.g., <code>Customer Registration Portal</code>).</li><li><strong>Site Description</strong>: Optional notes about the site&#39;s purpose and forms.</li><li><strong>Active Status</strong>: Enable or disable execution for this site.</li></ul></li><li>Click <strong>Save</strong> to create the site container.</li></ol><img src="/image/insert-site-manually-01.png" alt="Manual Site Creation Interface" style="max-width:480px;border-radius:8px;margin:16px 0;"><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Site Title</strong></td><td>Yes</td><td>Descriptive project name (up to 100 characters).</td></tr><tr><td><strong>Site Description</strong></td><td>No</td><td>Optional notes explaining the automation goal.</td></tr><tr><td><strong>Active Status</strong></td><td>Yes</td><td>Toggle switch to activate or pause the site.</td></tr></tbody></table><hr><h2 id="site-controls" tabindex="-1">Site Management Controls <a class="header-anchor" href="#site-controls" aria-label="Permalink to “Site Management Controls”">​</a></h2><p>Each site entry in the dashboard provides management actions:</p><h3 id="site-title-description" tabindex="-1">Site Title &amp; Description <a class="header-anchor" href="#site-title-description" aria-label="Permalink to “Site Title &amp; Description”">​</a></h3><ul><li><strong>Site Title</strong>: Identifies the project across extension views and export files.</li><li><strong>Site Description</strong>: Provides context for team members or future reference.</li></ul><h3 id="active-inactive-toggle" tabindex="-1">Active / Inactive Toggle <a class="header-anchor" href="#active-inactive-toggle" aria-label="Permalink to “Active / Inactive Toggle”">​</a></h3><ul><li><strong>Status Toggle</strong>: Quickly enable or pause automation for the entire site without deleting any forms, fields, or templates.</li></ul><h3 id="edit-site" tabindex="-1">Edit Site <a class="header-anchor" href="#edit-site" aria-label="Permalink to “Edit Site”">​</a></h3><ul><li>Opens the site workspace, containing tabs for: <ul><li><strong>Site Pages (Forms)</strong>: Manage target URLs and page-level automation.</li><li><strong>Segments</strong>: Build on-demand, reusable field routines.</li><li><strong>Excel Template</strong>: Download/upload <code>.xlsx</code> batch data and sync Google Sheets.</li><li><strong>Site Settings</strong>: Toggle execution flags, define site environment variables, and export backup files.</li><li><strong>Scraper Data</strong>: Inspect and export extracted page data.</li></ul></li></ul><h3 id="duplicate-site" tabindex="-1">Duplicate Site <a class="header-anchor" href="#duplicate-site" aria-label="Permalink to “Duplicate Site”">​</a></h3><ul><li>Creates an instant clone of the site, including all configured forms, segments, fields, and timing rules. Useful for staging vs. production environments.</li></ul><h3 id="copy-site-id" tabindex="-1">Copy Site ID <a class="header-anchor" href="#copy-site-id" aria-label="Permalink to “Copy Site ID”">​</a></h3><ul><li>Copies the unique internal alphanumeric ID for this site to your clipboard.</li><li><strong>Use Case</strong>: When browsing to subsequent pages of a multi-step form, press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd> (or select <strong>Insert Form</strong> from the context menu) and paste the Site ID to link the new page to this site.</li></ul><h3 id="delete-site" tabindex="-1">Delete Site <a class="header-anchor" href="#delete-site" aria-label="Permalink to “Delete Site”">​</a></h3><ul><li>Permanently removes the site container and all associated forms, segments, and field configurations.</li><li><strong>Recommendation</strong>: Export a site backup via <a href="/documentation/site/site-settings.html#export-site-data">Site Settings</a> before performing permanent deletions.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="site-not-created-from-context-menu" tabindex="-1">Site Not Created from Context Menu <a class="header-anchor" href="#site-not-created-from-context-menu" aria-label="Permalink to “Site Not Created from Context Menu”">​</a></h3><ul><li><strong>Extension Disabled</strong>: Verify that the extension is toggled <strong>ON</strong> in the browser toolbar.</li><li><strong>Restricted Pages</strong>: Browser extensions cannot execute on internal pages (such as <code>chrome://</code> or <code>edge://</code>) or web store listings.</li><li><strong>Right-Click Blocked</strong>: If the page prevents context menus via JavaScript, use the shortcut <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd> or enable <strong>Allow Right Click?</strong> in <a href="/documentation/settings.html#advanced-options">Settings</a>.</li><li><strong>Diagnostics</strong>: Check the built-in <a href="/documentation/logs.html">Logs</a> dashboard for execution details.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><p><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> — Configure execution toggles, site environment variables, and exports<br><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form/form.html#insert-site-form">Insert Site Form</a> — Add form pages and URL matching rules<br><img src="/svg/system.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments</a> — Build on-demand, reusable field routines<br><img src="/svg/code.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html#insert-field">Form Fields Configuration</a> — Set up individual form field selectors<br><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template Management</a> — Download and upload <code>.xlsx</code> spreadsheets</p>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};